input.command:
cd /private/tmp/claude-502/-Users-louis-Documents-TUM-semester-6-Sonstiges-EHL-Final/f89c83d3-cee0-47ca-a469-34c75151c5c8/scratchpad/pr12 && python3 -I - <<'E'
import json,glob,collections
rows=[]
for f in sorted(glob.glob('logs/sessions/practice/*.json')):
    s=json.load(open(f)); r=s.get('result') or {}
    st=[t.get('status') for t in s['threads'].values()]
    rows.append((s['case_id'][5:],s['session_id'][:6],r.get('score'),s['rounds'],s['end_reason'],','.join(map(str,st)),r))
by=collections.defaultdict(list)
for x in rows: by[x[0]].append(x)
print("case n  scores(sorted)  | end reasons")
for c,xs in by.items():
    sc=sorted(round(x[2] or 0,2) for x in xs)
    print(c,len(xs),sc,collections.Counter(x[4] for x in xs).most_common())
print()
print("best session per case: gap to best, non-price components")
for c,xs in by.items():
    b=max(xs,key=lambda x:x[2] or 0); r=b[6]
    cb=r.get('cost_breakdown',{}); gap=r['c_deal']-r['c_best']
    oth={k:round(v) for k,v in cb.items() if k!='price' and abs(v)>1}
    t=r['terms']
    print(c,b[1],'score',round(b[2],3),'rounds',b[3],'status',b[5],'gap',round(gap),'of',round(r['c_open']-r['c_best']),'price',t.get('unit_price'),'pay',t.get('payment_days'),'months',t.get('contract_months'),'|',oth)
print()
# rounds vs score, status at end
print("score by final status of chosen thread / rounds")
agg=collections.defaultdict(list)
for x in rows:
    if x[2] is not None: agg[x[3]].append(x[2])
for k in sorted(agg): print('rounds',k,'n',len(agg[k]),'mean',round(sum(agg[k])/len(agg[k]),2))
E

