input.command:
cd /private/tmp/claude-502/-Users-louis-Documents-TUM-semester-6-Sonstiges-EHL-Final/f89c83d3-cee0-47ca-a469-34c75151c5c8/scratchpad/pr12 && python3 -I - <<'E'
import json,glob,collections
for setn in('practice','sandbox'):
  print('=====',setn)
  for f in sorted(glob.glob(f'logs/sessions/{setn}/*.json')):
    s=json.load(open(f)); r=s.get('result') or {}
    tr=r.get('trace') or []
    th=collections.defaultdict(list); last={}
    for t in tr:
        m=t['move']; a=t['actor']
        if a=='buyer':
            sid=m.get('supplier_id')
            if m.get('type')=='message':
                ps=[ts['terms'].get('unit_price') for ts in m.get('term_sheets',[])]
                last[sid]=('/'.join(str(p) for p in ps) or '-')+('c%d'%len(m.get('interpreted',{}).get('claims',[])) )
            else: th[sid].append(m.get('type'))
        else:
            sg=m.get('signals') or {}
            st={'open':'o','agreed':'A','final_offer':'F','walked_away':'W','no_bid':'N'}.get(m.get('status'),m.get('status'))
            cr=''.join({'verified':'v','contradicted':'X','duplicate':'d','irrelevant':'i','unverifiable':'u'}.get(c['result'],'?') for c in m.get('claim_results',[]))
            th[a].append(f"{last.pop(a,'')}>{(m.get('terms') or {}).get('unit_price')}{st}[{sg.get('reply_delay_days')},{sg.get('validity_days')}]{cr}{'+alt' if m.get('alternatives') else ''}")
    sc=r.get('score')
    print(s['case_id'][5:],s['session_id'][:6],'%.2f'%(sc or 0),s['end_reason'])
    for a,v in th.items(): print('   ',a[4:],' '.join(map(str,v)))
E

